(()=>{"use strict";
if(!("serviceWorker"in navigator)||!window.isSecureContext)return;
const sw=new URL("./coi-serviceworker-sw.js",location.href).href;
navigator.serviceWorker.getRegistration("./").then(async r=>{
 if(r&&r.active&&r.active.scriptURL!==sw){await r.unregister();r=null}
 await navigator.serviceWorker.register(sw,{scope:"./"});
 if(!navigator.serviceWorker.controller&&!sessionStorage.getItem("movs-coi-reloaded")){
   sessionStorage.setItem("movs-coi-reloaded","1");location.reload();
 }
}).catch(console.error);
})();